        try:
            res = subprocess.run(
                [node_bin, tf_path],
                stdin=subprocess.DEVNULL,
                capture_output=True,
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=10,
            )
            self.assertEqual(
                res.returncode,
                0,
                f"Node execution failed with {res.stderr}\nScript:\n{harness_js[:1000]}",
            )
            self.assertIn("POLYGERRIT_FOLLOW_UP_DIALOG_OK", res.stdout)
        finally:
            if os.path.exists(tf_path):
                os.remove(tf_path)

