        self.assertIn("pg-footer-delta", html)
        self.assertIn("pg-footer-reviewed", html)
        self.assertIn('[data-pg-theme="light"] .pg-file-list-table tfoot', html)
        self.assertIn('[data-pg-theme="light"] .pg-delta-zero', html)

        self.assertIn("function getPgFileSizeInfo", html)
        self.assertIn("function renderPgFileSizeBadgeHtml", html)
        self.assertIn("function renderPgFileDeltaNumbersHtml", html)
        self.assertIn("function renderPgFileDeltaBarHtml", html)
        self.assertIn("function getPgFileSort", html)
