    def test_polygerrit_commit_message_inline_editor(self) -> None:
        """Verifies authentic PolyGerrit commit message inline editor (<gr-commit-message-editor>),

        real-time semantic commit validation, max line length indicators, intelligent 72-col body
        wrapping, in-place edit mode toggling, /COMMIT_MSG edit row action, REST API endpoint,
        and keyboard shortcut 'e'.
        """
        import os
        import re
        import subprocess
        import tempfile
        from unittest.mock import MagicMock, patch
        from lib.gerrit_api import GerritClient
        from commands.gerrit.services.vote_submit_service import GerritVoteSubmitService
        from commands.gerrit.services.diff_parser import get_gerrit_ui_template_path

        # 1. Backend GerritClient.set_commit_message verification
        real_client = GerritClient(host="https://android-review.googlesource.com")
        real_client._request_raw = MagicMock(return_value="{}")

        unicode_msg = (
            "feat(gerrit): Support Unicode 测试_🚀_é and polish\n\n"
            "Explain what changed and why it is needed.\n\n"
            "Bug: 123456\n"
            "Test: bazel test @aemu//...\n"
            "Change-Id: I1234567890abcdef1234567890abcdef12345678"
        )
        res = real_client.set_commit_message("43330099", unicode_msg)
        self.assertEqual(res["status"], "ok")
        self.assertEqual(res["change_id"], "43330099")
        self.assertEqual(res["message"], unicode_msg)
        self.assertEqual(res["notify"], "OWNER")
        real_client._request_raw.assert_called_once()
        call_args = real_client._request_raw.call_args
        self.assertIn("/a/changes/43330099/message", call_args[0][0])
        self.assertEqual(call_args[1]["method"], "PUT")
        self.assertEqual(call_args[1]["data"]["message"], unicode_msg)
        self.assertEqual(call_args[1]["data"]["notify"], "OWNER")

        # 2. Backend GerritVoteSubmitService.save_commit_message verification
        mock_vote_client = MagicMock(spec=GerritClient)
        mock_vote_client.set_commit_message.return_value = {"status": "ok"}
        with patch("commands.gerrit.services.diff_parser.GerritClient"):
            service = GerritVoteSubmitService(host="https://android-review.googlesource.com")
        service.client = mock_vote_client
        save_res = service.save_commit_message(43330099, unicode_msg)
        self.assertEqual(save_res["status"], "ok")
        self.assertEqual(save_res["cl"], "43330099")
        self.assertEqual(save_res["action"], "edit_commit_message")
        self.assertEqual(save_res["notify"], "OWNER")
        mock_vote_client.set_commit_message.assert_called_once_with(
            "43330099", unicode_msg, notify="OWNER"
        )

        with self.assertRaises(ValueError):
            service.save_commit_message(43330099, "   ")

        # 3. Static template DOM tokens, CSS classes, and helper functions
