        try:
            res = subprocess.run(
                [node_bin, script_path],
                capture_output=True,
                text=True,
                encoding="utf-8",
                check=False,
            )
            self.assertEqual(
                res.returncode,
                0,
                f"Headless Node harness failed for PolyGerrit add comment shortcut & file header action:\nSTDERR:\n{res.stderr}\nSTDOUT:\n{res.stdout}",
            )
            self.assertIn("POLYGERRIT_ADD_COMMENT_SHORTCUT_AND_FILE_HEADER_ACTION_OK", res.stdout)
        finally:
            if os.path.exists(script_path):
                os.remove(script_path)

