    def test_polygerrit_metadata_hashtags_and_filtering(self) -> None:
        """Verifies PolyGerrit change metadata hashtags (<gr-change-metadata>), dashboard mini chips, and search filters."""
        import os
        import re
        import subprocess
        import tempfile
        from commands.gerrit.services.queue_service import enrich_change_for_ui
        from commands.gerrit.ui_server import render_static_gerrit_ui_html

        # 1. Backend service assertions for hashtags extraction & default
        cl_with_tags = {
            "_number": 43350001,
            "project": "platform/hardware/google/aemu",
            "branch": "studio-main",
            "subject": "feat(gerrit): Test hashtags support 测试_🚀_é",
            "hashtags": ["aemu-next", "flake-fix", "测试_🚀_é"],
            "owner": {"email": "author@google.com", "name": "Author 测试_🚀_é"},
        }
        res_with = enrich_change_for_ui(cl_with_tags, viewer_email="author@google.com")
        self.assertIn("hashtags", res_with)
        self.assertEqual(res_with["hashtags"], ["aemu-next", "flake-fix", "测试_🚀_é"])

        cl_empty_tags = {
            "_number": 43350002,
            "project": "platform/hardware/google/aemu",
            "branch": "studio-main",
            "subject": "fix(gerrit): Empty hashtags",
        }
        res_empty = enrich_change_for_ui(cl_empty_tags, viewer_email="author@google.com")
        self.assertIn("hashtags", res_empty)
        self.assertEqual(res_empty["hashtags"], [])

        # 2. Static HTML/CSS assertions on PolyGerrit template
        pg_html = render_static_gerrit_ui_html(variant="polygerrit")
        for expected_token in (
            "pg-meta-hashtags-row",
            "pg-meta-hashtags-val",
            "pg-hashtag-chip",
            "pg-btn-add-hashtag",
            "pg-add-hashtag-inline",
            "pg-hashtag-chip-mini",
            "filterDashboardByHashtag",
            "applyPgHashtagFilter",
            "copyPgHashtag",
            "addPgHashtag",
            "removePgHashtag",
            "showPgAddHashtagInput",
            "hidePgAddHashtagInput",
            "submitPgAddHashtag",
            "onPgAddHashtagKeyDown",
            "window.renderCommitReviewersPanelHtml = renderCommitReviewersPanelHtml;",
            "window.renderPgDashboardRowHtml = renderPgDashboardRowHtml;",
            "window.filterDashboardByHashtag = filterDashboardByHashtag;",
            "window.applyPgHashtagFilter = applyPgHashtagFilter;",
            "window.copyPgHashtag = copyPgHashtag;",
            "window.addPgHashtag = addPgHashtag;",
            "window.removePgHashtag = removePgHashtag;",
            'op: "hashtag:",',
            'op: "has:hashtag",',
            'keys: ["Alt", "H"]',
            '[data-pg-theme="light"] .pg-hashtag-chip',
            '[data-pg-theme="light"] .pg-hashtag-chip-mini',
        ):
            self.assertIn(
                expected_token,
                pg_html,
                msg=f"Expected token '{expected_token}' to be present in PolyGerrit UI template",
            )

        # 3. Headless Node / VM DOM test harness
        node_bin = _resolve_node_bin(self)
        if not node_bin:
            return

        scripts = re.findall(r"<script(?![^>]*\bsrc=)[^>]*>(.*?)</script>", pg_html, flags=re.S)
        self.assertTrue(scripts)
