    def test_polygerrit_diff_chunk_navigation_and_shortcuts(self):
        """Verifies PolyGerrit diff chunk navigation engine (n/p), chunk grouping, SBS/Unified support, and Shift+Alt+N/P shortcuts."""
        from commands.gerrit.services.diff_parser import get_gerrit_ui_template_path

        tpl_path = get_gerrit_ui_template_path("polygerrit")
