    def test_polygerrit_commit_header_nav_buttons_and_hotkeys(self) -> None:
        """Test moving commit prev/next navigation buttons up into the header actions area alongside Harness Actions."""
        import os
        import subprocess
        import tempfile
        from commands.gerrit.ui_server import render_static_gerrit_ui_html

        # 1. Static HTML / CSS token assertions
        pg_html = render_static_gerrit_ui_html(
            initial_payload={"viewer": "tester@google.com"},
            variant="polygerrit",
        )

        for expected_token in (
            "function renderCommitNavButtonsHtml(",
            'id="btnNavPrev"',
            'id="btnNavNext"',
            "navigateVisibleCl('prev')",
            "navigateVisibleCl('next')",
            "[data-pg-theme=\"light\"] .btn.btn-nav-cl",
            "@media (max-width: 1120px)",
            ".pg-commit-actions {",
        ):
            self.assertIn(expected_token, pg_html)

        # Assert renderCommitNavButtonsHtml is inside renderCommitHarnessActionsHtml in the harness area
        harness_fn_idx = pg_html.index("function renderCommitHarnessActionsHtml(c, bundle = null)")
        nav_call_idx = pg_html.index("renderCommitNavButtonsHtml()", harness_fn_idx)
        harness_group_idx = pg_html.index('class="harness-group"', harness_fn_idx)
        nav_embed_idx = pg_html.index("${navBtnsHtml}", harness_group_idx)
        harness_toggle_idx = pg_html.index('id="btnHarnessMenuToggle"', harness_group_idx)
        self.assertLess(nav_embed_idx, harness_toggle_idx)

        # Assert renderPgChangeHeaderHtml embeds the harness actions area
        header_fn_idx = pg_html.index("function renderPgChangeHeaderHtml(c, bundle)")
        header_actions_idx = pg_html.index('class="pg-commit-actions commit-sec-actions"', header_fn_idx)
        harness_call_idx = pg_html.index("${renderCommitHarnessActionsHtml(c", header_actions_idx)
        self.assertGreater(harness_call_idx, header_actions_idx)

        # Assert renderCommitNavButtonsHtml is NOT duplicated in diff or checks controls
        files_controls_idx = pg_html.index('id="pgFilesControls-${c.number}"')
        pane_close_idx = pg_html.index('id="pgFilesTabPane-${c.number}"')
        files_controls_slice = pg_html[files_controls_idx:pane_close_idx]
        self.assertNotIn("${renderCommitNavButtonsHtml()}", files_controls_slice)

        checks_fn_idx = pg_html.index("function renderPgChecksControlsHtml(c)")
