        self.assertIn("renderPgTrailingContextControlBarHtml", html)
        self.assertIn("Expand trailing context lines below diff to EOF", html)

        # 2. Python diff_parser assertions for total_lines handling
        from commands.gerrit.services.diff_parser import parse_unified_diff_files

        unicode_file = "emulator/libs/file/测试_🚀_é.cc"
        sample_patch = (
            f"diff --git a/{unicode_file} b/{unicode_file}\n"
            "--- a/emulator/libs/file/测试_🚀_é.cc\n"
            "+++ b/emulator/libs/file/测试_🚀_é.cc\n"
            "@@ -10,3 +10,4 @@ void init()\n"
            " int a = 1;\n"
            "+int b = 2;\n"
            " int c = 3;\n"
        )
        files = parse_unified_diff_files(
            sample_patch, file_total_lines={unicode_file: 150}
        )
        self.assertEqual(len(files), 1)
        self.assertEqual(files[0]["file"], unicode_file)
        self.assertEqual(files[0]["total_lines"], 150)

        added_patch = (
            "diff --git a/new_file.txt b/new_file.txt\n"
            "new file mode 100644\n"
            "--- /dev/null\n"
            "+++ b/new_file.txt\n"
            "@@ -0,0 +1,3 @@\n"
            "+line 1\n"
            "+line 2\n"
            "+line 3\n"
        )
        added_files = parse_unified_diff_files(added_patch)
        self.assertEqual(added_files[0]["status"], "A")
        self.assertEqual(added_files[0]["total_lines"], 3)

        deleted_patch = (
            "diff --git a/old_file.txt b/old_file.txt\n"
            "deleted file mode 100644\n"
            "--- a/old_file.txt\n"
            "+++ /dev/null\n"
            "@@ -1,2 +0,0 @@\n"
            "-line 1\n"
            "-line 2\n"
        )
        deleted_files = parse_unified_diff_files(deleted_patch)
        self.assertEqual(deleted_files[0]["status"], "D")
        self.assertEqual(deleted_files[0]["total_lines"], 0)

