    def test_polygerrit_file_diff_symbol_outline_and_quick_jump(self) -> None:
        """Verifies PolyGerrit diff viewer inline symbol outline extraction and quick jump navigation."""
        from commands.gerrit.services.diff_parser import (
            get_gerrit_ui_template_path,
            parse_unified_diff_files,
        )

        template_path = get_gerrit_ui_template_path("polygerrit")
        self.assertTrue(template_path.exists())
        pg_html = template_path.read_text(encoding="utf-8")

        # 1. Static HTML/JS/CSS assertions
        self.assertIn("extractPgFileDiffSymbols", pg_html)
        self.assertIn("renderPgFileOutlineButtonHtml", pg_html)
        self.assertIn("renderPgFileOutlineDropdownHtml", pg_html)
        self.assertIn("togglePgFileOutlineMenu", pg_html)
        self.assertIn("closeAllPgFileOutlineMenus", pg_html)
        self.assertIn("jumpToPgFileSymbol", pg_html)
        self.assertIn("onPgFileOutlineFilterInput", pg_html)
        self.assertIn(".pg-file-outline-wrap", pg_html)
        self.assertIn(".pg-btn-file-outline", pg_html)
        self.assertIn(".pg-file-outline-dropdown", pg_html)
        self.assertIn(".pg-outline-item", pg_html)
        self.assertIn(".pg-symbol-jump-highlight", pg_html)

        # 2. Backend diff_parser extraction of symbols (C++, Python, Unicode)
        sample_diff = (
            "diff --git a/emulator/device.cc b/emulator/device.cc\n"
            "index 1111111..2222222 100644\n"
            "--- a/emulator/device.cc\n"
            "+++ b/emulator/device.cc\n"
            "@@ -20,6 +20,12 @@ class DeviceController {\n"
            "   int state_;\n"
            "+  void InitDevice(int timeout) {\n"
            "+    state_ = timeout;\n"
            "+  }\n"
            " };\n"
            "@@ -50,4 +56,10 @@ void ProcessPacket(void* buf) {\n"
            "   if (!buf) return;\n"
            "+  void 测试_🚀_é() {\n"
            "+    LOG(INFO) << \"Unicode packet\";\n"
            "+  }\n"
            " }\n"
        )
        parsed = parse_unified_diff_files(sample_diff)
        self.assertEqual(len(parsed), 1)
        symbols = parsed[0].get("symbols", [])
        self.assertGreaterEqual(len(symbols), 2)
        symbol_names = [s["name"] for s in symbols]
        self.assertTrue(any("DeviceController" in n or "InitDevice" in n for n in symbol_names))
        self.assertTrue(any("ProcessPacket" in n or "测试_🚀_é" in n for n in symbol_names))

        # 3. Headless Node VM harness testing outline DOM and interactions
