    def test_polygerrit_commit_message_no_text_overlap_under_diff_wrap(self):
        """Verify commit message cells and children do not inherit negative text-indent from .pg-diff-wrap-lines."""
        pg_tpl_path = (
            Path(__file__).resolve().parents[1]
            / "src"
            / "templates"
            / "gerrit_ui_polygerrit.html"
        )
        pg_html = pg_tpl_path.read_text(encoding="utf-8")

        self.assertIn(
            ".pg-diff-wrap-lines .code-text:not(.code-hunk-text):not(.commit-msg-cell)",
            pg_html,
        )
        self.assertIn(
            ".commit-msg-cell *\n  {",
            pg_html.replace(" {\n", "\n  {"),
        )
        self.assertIn(
            ".pg-diff-wrap-lines .code-text.commit-msg-cell",
            pg_html,
        )
        self.assertIn(
            ".commit-msg-footer-line > :not(.commit-msg-footer-key):not(.pg-btn-copy-trailer)",
            pg_html,
        )

